// Read the values Lua published into the shared `nb` state
const fib = nb.get('fib');
const sum = nb.get('fib_sum');
console.log('Lua sent fib =', fib);
console.log('Lua sent fib_sum =', sum);

// Use them like any JS data
const doubled = fib.map(x => x * 2);
return { fib, sum, doubled, average: sum / fib.length };
